import{_ as e,o as a,c as n,a4 as t}from"./chunks/framework.CQGI5ZO3.js";const D=JSON.parse('{"title":"xs-recipes(7)","description":"Complete, tested workflows — snapshots, safe mirrors, a Raspberry Pi, scheduled backups — with their real output.","frontmatter":{"title":"xs-recipes(7)","description":"Complete, tested workflows — snapshots, safe mirrors, a Raspberry Pi, scheduled backups — with their real output.","manual":"xs-recipes(7)","manualName":"Recipes","sectionNumber":"7"},"headers":[],"relativePath":"recipes.md","filePath":"recipes.md"}'),o={name:"recipes.md"};function l(p,s,c,r,i,E){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="xs-recipes-7" tabindex="-1">xs-recipes(7) <a class="header-anchor" href="#xs-recipes-7" aria-label="Permalink to &quot;xs-recipes(7)&quot;">​</a></h1><div class="manual-deck"><strong>Recipes</strong><p>Complete, tested workflows — snapshots, safe mirrors, a Raspberry Pi, scheduled backups — with their real output.</p></div><h2 id="about" tabindex="-1">ABOUT THESE RECIPES <a class="header-anchor" href="#about" aria-label="Permalink to &quot;ABOUT THESE RECIPES {#about}&quot;">​</a></h2><p>Each recipe below was run against the current binary in a disposable directory, and the output shown is what it printed. Remote recipes went through an ssh stand-in that runs the other side on the same machine, so <code>host:backup/</code> is a directory next to the source. Replace <code>src/</code>, <code>dst/</code> and the host names with your own.</p><h2 id="snapshots" tabindex="-1">DATED SNAPSHOTS <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;DATED SNAPSHOTS {#snapshots}&quot;">​</a></h2><p>Keep one directory per day. Each new snapshot hard-links every unchanged file to the previous day’s copy, so a full-looking snapshot costs only the space of what changed.</p><div class="example-caption">Dated snapshots that share unchanged files</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">snapshot() {</span></span>
<span class="line"><span style="color:#DEDEDE;">  previous=$(ls </span><span style="color:#DEDEDE;">-1</span><span style="color:#DEDEDE;"> snapshots</span><span style="color:#DEDEDE;"> | tail </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 1</span><span style="color:#DEDEDE;">)</span></span>
<span class="line"><span style="color:#DEDEDE;">  xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> \${previous:+--link-dest=../$previous} </span><span style="color:#DEDEDE;">src/</span><span style="color:#DEDEDE;"> &quot;snapshots/$1/&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">}</span></span>
<span class="line"><span style="color:#DEDEDE;">snapshot </span><span style="color:#DEDEDE;">2026-10-09</span></span>
<span class="line"><span style="color:#DEDEDE;">printf </span><span style="color:#DEDEDE;">&#39;Action items\\n&#39;</span><span style="color:#DEDEDE;"> &gt;&gt; </span><span style="color:#DEDEDE;">src/notes.txt</span></span>
<span class="line"><span style="color:#DEDEDE;">snapshot </span><span style="color:#DEDEDE;">2026-10-10</span></span>
<span class="line"><span style="color:#DEDEDE;">ls </span><span style="color:#DEDEDE;">snapshots</span></span>
<span class="line"><span style="color:#DEDEDE;">stat </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &#39;%h links  %n&#39;</span><span style="color:#DEDEDE;"> snapshots/*/notes.txt</span><span style="color:#DEDEDE;"> snapshots/*/docs/guide.md</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>2026-10-09
2026-10-10
1 links  snapshots/2026-10-09/notes.txt
1 links  snapshots/2026-10-10/notes.txt
2 links  snapshots/2026-10-09/docs/guide.md
2 links  snapshots/2026-10-10/docs/guide.md</code></pre></div><p><code>notes.txt</code> changed, so each snapshot has its own copy (1 link). <code>guide.md</code> did not, so both snapshots share one file (2 links). Deleting an old snapshot directory frees only the files no other snapshot shares. Treat snapshots as read-only: an in-place write or metadata change to a shared file changes it in every snapshot (<a href="snapshots.html#shared-files">shared files</a>).</p><h2 id="mirror" tabindex="-1">A SAFE MIRROR <a class="header-anchor" href="#mirror" aria-label="Permalink to &quot;A SAFE MIRROR {#mirror}&quot;">​</a></h2><p>Preview first. The dry run prints the same itemized plan the real run will perform, and ends with a one-line summary.</p><div class="example-caption">Preview a mirror</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ani</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>.d..t...... ./
.d..t...... docs/
&gt;f+++++++++ docs/draft.md
.d..t...... docs/images/
*deleting   docs/images/diagram.svg
*deleting   old/
*deleting   old/a.txt
*deleting   old/b.txt
would transfer 1 files (6B), delete 4</code></pre></div><p>If the plan is what you expect, run it with a deletion limit somewhat above the planned count. A mistaken source path, such as an unmounted disk, then stops at the limit (exit 25) rather than emptying the destination.</p><div class="example-caption">Run the reviewed mirror with a deletion limit</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ai</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --max-delete=10</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>.d..t...... ./
.d..t...... docs/
&gt;f+++++++++ docs/draft.md
.d..t...... docs/images/
*deleting   docs/images/diagram.svg
*deleting   old/
*deleting   old/a.txt
*deleting   old/b.txt</code></pre></div><h2 id="raspberry-pi" tabindex="-1">A RASPBERRY PI, OR ANY HOST WITHOUT XS <a class="header-anchor" href="#raspberry-pi" aria-label="Permalink to &quot;A RASPBERRY PI, OR ANY HOST WITHOUT XS {#raspberry-pi}&quot;">​</a></h2><p>Build the release binaries once (<a href="install.html#releases">release binaries</a>), install the helper, then push natively. The installer picks the ARM64 build for a 64-bit Pi.</p><div class="example-caption">Install xs on a host that does not have it, then push natively</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">export XSYNC_RELEASE_DIR=releases</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> user@pi</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azi</span><span style="color:#DEDEDE;"> --no-fallback</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@pi:backup/</span><span style="color:#DEDEDE;"> | tail </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 3</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>Installed xs-linux-amd64 on user@pi at ~/.local/bin/xs
xs  version 0.1.0  protocol version 4  git d3a49f8872fd
&lt;f+++++++++ notes.txt
cd+++++++++ scripts/
&lt;f+++++++++ scripts/build.sh</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><p>Without the helper, the same push still works but runs rsync, with a notice (<a href="troubleshooting.html#fallback">troubleshooting</a>). Adding <code>--no-fallback</code>, as here, proves the native path was used.</p><h2 id="find" tabindex="-1">FILES CHOSEN BY FIND <a class="header-anchor" href="#find" aria-label="Permalink to &quot;FILES CHOSEN BY FIND {#find}&quot;">​</a></h2><div class="example-caption">Copy the files find selects, with NUL delimiters</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">(cd </span><span style="color:#DEDEDE;">src</span><span style="color:#DEDEDE;"> &amp;&amp; find </span><span style="color:#DEDEDE;">.</span><span style="color:#DEDEDE;"> -name</span><span style="color:#DEDEDE;"> &#39;*.md&#39;</span><span style="color:#DEDEDE;"> -print0</span><span style="color:#DEDEDE;">) | xs </span><span style="color:#DEDEDE;">-ai0</span><span style="color:#DEDEDE;"> --files-from=-</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>cd+++++++++ ./
cd+++++++++ docs/
&gt;f+++++++++ docs/guide.md
&gt;f+++++++++ docs/odd\\#012name.md</code></pre></div><p>Run <code>find</code> from inside the source so the names are relative to it, and use <code>-print0</code> with <code>-0</code> so any filename survives, newlines included. In the output, xs escapes the newline as <code>\\#012</code>. With <code>--files-from</code>, <code>-a</code> does not recurse into listed directories; add <code>-r</code> if the list names directories whose contents you want.</p><h2 id="scheduled" tabindex="-1">A SCHEDULED BACKUP <a class="header-anchor" href="#scheduled" aria-label="Permalink to &quot;A SCHEDULED BACKUP {#scheduled}&quot;">​</a></h2><div class="example-caption">A scheduled backup that logs and keeps the exit status</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cat &gt; </span><span style="color:#DEDEDE;">backup.sh</span><span style="color:#DEDEDE;"> &lt;&lt;</span><span style="color:#DEDEDE;">&#39;SH&#39;</span></span>
<span class="line"><span style="color:#DEDEDE;">#!/bin/sh</span></span>
<span class="line"><span style="color:#DEDEDE;">log=backup.log</span></span>
<span class="line"><span style="color:#DEDEDE;">xs -a --delete --log-file=&quot;$log&quot; --out-format=&#39;%t %i %n&#39; src/ dst/ &gt; /dev/null</span></span>
<span class="line"><span style="color:#DEDEDE;">status=$?</span></span>
<span class="line"><span style="color:#DEDEDE;">echo &quot;$(date -u &#39;+%Y/%m/%d %H:%M:%S&#39;) finished with exit status $status&quot; &gt;&gt; &quot;$log&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">exit $status</span></span>
<span class="line"><span style="color:#DEDEDE;">SH</span></span>
<span class="line"><span style="color:#DEDEDE;">sh </span><span style="color:#DEDEDE;">backup.sh</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">head </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 3</span><span style="color:#DEDEDE;"> backup.log</span><span style="color:#DEDEDE;">; tail </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 1</span><span style="color:#DEDEDE;"> backup.log</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>exit status: 0
2026/10/10 16:32:52 cd+++++++++ ./
2026/10/10 16:32:52 cd+++++++++ archive/
2026/10/10 16:32:52 &gt;f+++++++++ archive/2026-q3.log
2026/10/10 16:32:52 finished with exit status 0</code></pre></div><p>The log gets the same lines stdout would, plus the script’s final status line, and the script exits with xs’s status so the scheduler can alert on failure. Progress stays off on its own, because a scheduler’s stderr is not a terminal. Personal defaults still apply; set <code>XSYNC_CONFIG=&#39;&#39;</code> and <code>XSYNC_OPTS=&#39;&#39;</code> in the job if they should not.</p><div class="example-caption">Run it nightly at 02:30: a crontab line (scheduler configuration, not captured)</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">30 </span><span style="color:#DEDEDE;">2</span><span style="color:#DEDEDE;"> *</span><span style="color:#DEDEDE;"> *</span><span style="color:#DEDEDE;"> *</span><span style="color:#DEDEDE;"> cd</span><span style="color:#DEDEDE;"> /path/to/backups</span><span style="color:#DEDEDE;"> &amp;&amp; sh </span><span style="color:#DEDEDE;">backup.sh</span></span></code></pre></div><div class="example-caption">The same with launchd on macOS: ~/Library/LaunchAgents/local.backup.plist (not captured)</div><div class="language-xml"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">&lt;?xml version=</span><span style="color:#DEDEDE;">&quot;1.0&quot;</span><span style="color:#DEDEDE;"> encoding=</span><span style="color:#DEDEDE;">&quot;UTF-8&quot;</span><span style="color:#DEDEDE;">?&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">&lt;!DOCTYPE plist PUBLIC &quot;-//Apple//DTD PLIST 1.0//EN&quot; &quot;http://www.apple.com/DTDs/PropertyList-1.0.dtd&quot;&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">&lt;plist version=</span><span style="color:#DEDEDE;">&quot;1.0&quot;</span><span style="color:#DEDEDE;">&gt;&lt;dict&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">  &lt;key&gt;Label&lt;/key&gt;&lt;string&gt;local.backup&lt;/string&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">  &lt;key&gt;WorkingDirectory&lt;/key&gt;&lt;string&gt;/path/to/backups&lt;/string&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">  &lt;key&gt;ProgramArguments&lt;/key&gt;&lt;array&gt;&lt;string&gt;/bin/sh&lt;/string&gt;&lt;string&gt;backup.sh&lt;/string&gt;&lt;/array&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">  &lt;key&gt;StartCalendarInterval&lt;/key&gt;&lt;dict&gt;&lt;key&gt;Hour&lt;/key&gt;&lt;integer&gt;2&lt;/integer&gt;&lt;key&gt;Minute&lt;/key&gt;&lt;integer&gt;30&lt;/integer&gt;&lt;/dict&gt;</span></span>
<span class="line"><span style="color:#DEDEDE;">&lt;/dict&gt;&lt;/plist&gt;</span></span></code></pre></div><h2 id="json" tabindex="-1">A WRAPPER THAT READS JSON EVENTS <a class="header-anchor" href="#json" aria-label="Permalink to &quot;A WRAPPER THAT READS JSON EVENTS {#json}&quot;">​</a></h2><div class="example-caption">A Python consumer that ignores diagnostics and reports the outcome</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt; </span><span style="color:#DEDEDE;">events.ndjson</span></span>
<span class="line"><span style="color:#DEDEDE;">python3 </span><span style="color:#DEDEDE;">-</span><span style="color:#DEDEDE;"> events.ndjson</span><span style="color:#DEDEDE;"> &lt;&lt;</span><span style="color:#DEDEDE;">&#39;PY&#39;</span></span>
<span class="line"><span style="color:#DEDEDE;">import json, sys</span></span>
<span class="line"><span style="color:#DEDEDE;">events = [json.loads(line) for line in open(sys.argv[1]) if line.startswith(&#39;{&#39;)]</span></span>
<span class="line"><span style="color:#DEDEDE;">files = [e for e in events if e[&#39;type&#39;] == &#39;file&#39;]</span></span>
<span class="line"><span style="color:#DEDEDE;">done = events[-1]</span></span>
<span class="line"><span style="color:#DEDEDE;">print(f&quot;{len(files)} files, {sum(e[&#39;bytes&#39;] for e in files):,} bytes sent&quot;)</span></span>
<span class="line"><span style="color:#DEDEDE;">print(f&quot;deleted {done[&#39;deleted&#39;]}, exit {done[&#39;exit_code&#39;]}, success {done[&#39;success&#39;]}&quot;)</span></span>
<span class="line"><span style="color:#DEDEDE;">PY</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>5 files, 1,289,005 bytes sent
deleted 1, exit 0, success True</code></pre></div><p>Diagnostics share stderr with the events, so keep only lines that start with <code>{</code>. The last event is always <code>complete</code> once a transfer has started; check the process status too, for failures before it starts. Every field is documented in <a href="json-events.html">JSON progress events</a>.</p><h2 id="overnight" tabindex="-1">AN OVERNIGHT PUSH ON A SLOW LINK <a class="header-anchor" href="#overnight" aria-label="Permalink to &quot;AN OVERNIGHT PUSH ON A SLOW LINK {#overnight}&quot;">​</a></h2><div class="example-caption">A bandwidth-limited push that gives up on a stalled link</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-az</span><span style="color:#DEDEDE;"> --bwlimit=2M</span><span style="color:#DEDEDE;"> --timeout=60</span><span style="color:#DEDEDE;"> --stats</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> host:backup/</span><span style="color:#DEDEDE;"> | tail </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 4</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>Total bytes received: 138

sent 114,201 bytes  received 138 bytes  1,239,824.17 bytes/sec
total size is 1,289,005  speedup is 11.27</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><p><code>--bwlimit</code> caps the bytes on the wire after compression, so <code>-z</code> moves more file data within the same budget. <code>--timeout=60</code> ends the run with exit 30 if the connection stops moving for a minute; keep-alives stop an idle but healthy connection from tripping it. Run it again in the morning: completed files are skipped, and <code>-P</code> would also resume a large file that was cut off.</p><h2 id="preserve" tabindex="-1">PRESERVING EVERYTHING <a class="header-anchor" href="#preserve" aria-label="Permalink to &quot;PRESERVING EVERYTHING {#preserve}&quot;">​</a></h2><div class="example-caption">Preserve hard links, ACLs and extended attributes (Linux)</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aHAXi</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> | head </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 6</span></span>
<span class="line"><span style="color:#DEDEDE;">getfacl </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> dst/notes.txt</span><span style="color:#DEDEDE;"> | grep </span><span style="color:#DEDEDE;">nobody</span><span style="color:#DEDEDE;">; getfattr </span><span style="color:#DEDEDE;">-d</span><span style="color:#DEDEDE;"> dst/docs/guide.md</span><span style="color:#DEDEDE;"> 2&gt;</span><span style="color:#DEDEDE;">/dev/null</span><span style="color:#DEDEDE;"> | grep </span><span style="color:#DEDEDE;">origin</span><span style="color:#DEDEDE;"> || python3 </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &quot;import os; print(os.getxattr(&#39;dst/docs/guide.md&#39;, &#39;user.origin&#39;))&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>cd+++++++++ ./
cd+++++++++ archive/
&gt;f+++++++++ archive/2026-q3.log
cd+++++++++ docs/
&gt;f+++++++++ docs/guide.md
cd+++++++++ docs/images/
user:nobody:r--
b&#39;scanner&#39;</code></pre></div><p>On Linux, <code>-aHAX</code> adds hard links, ACLs and extended attributes to archive mode. On macOS, add <code>-N</code> for creation times and <code>--fileflags</code> for BSD flags: <code>xs -aHAXN --fileflags src/ dst/</code> (not captured here, because this page is captured on Linux). Remote ACLs need both hosts on the same platform. A macOS ↔ Linux <code>-A</code> transfer falls back to rsync, and rsync rejected the tested cross-platform ACLs too, so fallback is no guarantee of a conversion.</p>`,54)])])}const h=e(o,[["render",l]]);export{D as __pageData,h as default};
